import java.io.*;
import java.util.*;

public class Main implements Runnable{
    public static void main(String[] args){
        new Main().execute();
    }
    int mod=998244353;
    private void execute() {
        try{
            InputStream inStream=System.in;
            OutputStream outStream=System.out;
            Scanner scanner=new Scanner(inStream);
            int n=scanner.nextInt(),k=scanner.nextInt(),l=scanner.nextInt();
            long[]fac=new long[n+1];
            fac[0]=1;
            for(int i=1;i<=n;i++){
                fac[i]=fac[i-1]*i%mod;
            }
            long[][]dp=new long[2*n+1][2*n+2];
            dp[0][0]=1;
            for(int i=1;i<=2*n;i++){
                for(int j=0;j<=i;j++){
                    if(j>0) dp[i][j]=(dp[i][j]+dp[i-1][j-1])%mod;
                    dp[i][j]=(dp[i][j]+dp[i-1][j+1]*(j+1)%mod)%mod;
                }
            }
            long ans=0;
            for(int i=k;i<=2*n;i++){
                for(int j=k;j<=n;j++){
                    ans=(ans+dp[i][j]*dp[2*n-i][j]%mod*fac[j]%mod)%mod;
                }
            }
            long inv1=powMod(dp[2*n][0],mod-2);
            long inv2=powMod(2*n+1,mod-2);
            long result=l*ans%mod*inv1%mod*inv2%mod;
            System.out.println(result);
        }catch(Exception e){
            e.printStackTrace();
        }
    }
    private long powMod(long base, int exp){
        long result=1;
        while(exp>0){
            if((exp&1)==1) result=(result*base)%mod;
            base=(base*base)%mod;
            exp>>=1;
        }
        return result;
    }
}
